<script setup>
import { computed } from 'vue'
import SharedMetric from './SharedMetric.vue'
import MetricVisualization from './MetricVisualization.vue'
import { metricStatus } from './dashboard-orchestrator.mjs'
const props = defineProps({ plan:{type:Object,required:true}, state:String, demo:Boolean })
const emit=defineEmits(['return','focus','discuss','open'])
const primary = computed(()=>props.plan.metrics.find(item=>['available','partial'].includes(item.state)) || props.plan.metrics[0])
const modeLabel=computed(()=>props.plan.moduleCode?.toUpperCase() || 'PRIORITY')
const positions=computed(()=>{
 const n=props.plan.metrics.length
 if(props.plan.mode==='sem-focus') return [{x:22,y:24},{x:78,y:24},{x:50,y:61},{x:50,y:88}]
 if(props.plan.mode==='geo-focus') return [{x:50,y:25},{x:20,y:66},{x:80,y:66},{x:35,y:90},{x:65,y:90}]
 return n===1?[{x:50,y:57}]:n===2?[{x:25,y:65},{x:75,y:65}]:[{x:23,y:51},{x:77,y:51},{x:50,y:86}]
})
const center=computed(()=>props.plan.mode==='sem-focus'?{x:50,y:39}:props.plan.mode==='geo-focus'?{x:50,y:25}:{x:50,y:24})
</script>
<template>
  <section class="focus-response" :class="[`focus-${plan.mode}`,`phase-${state}`]" aria-label="AI 生成的数据视图">
    <header class="focus-heading"><div><small>AI FOCUS · {{ modeLabel }}<span v-if="demo"> · 演示数据</span></small><h2>{{ plan.title }}</h2><p>{{ plan.question }}</p></div><button type="button" @click="emit('return')">返回全域 ↗</button></header>
    <div v-if="plan.metrics.length" class="metric-space" :class="{'is-assembling':state==='assembling'}">
      <svg class="relationship-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path v-for="(card,index) in plan.metrics" :key="card.id" :d="`M${center.x} ${center.y} Q${positions[index].x} ${center.y} ${positions[index].x} ${positions[index].y}`" pathLength="1" :style="{'--node-delay':`${index*90}ms`}" /></svg>
      <div v-if="plan.mode==='priority'" class="space-origin priority-origin"><strong>{{ String(plan.metrics.length).padStart(2,'0') }}</strong><span>值得核对的关注依据</span></div>
      <div v-else-if="plan.mode==='sem-focus'" class="space-origin sem-origin"><i></i><b>SEM</b><span>曝光 · 点击 · 成本</span></div>
      <button v-for="(card,index) in plan.metrics" :key="card.id" type="button" class="floating-metric" :class="[`metric-${card.moduleCode}`,{'geo-core':plan.mode==='geo-focus'&&index===0}]" :style="{left:`${positions[index].x}%`,top:`${positions[index].y}%`,'--node-delay':`${index*90}ms`}" @click="emit('focus',card.id)">
        <span class="node-label"><em>{{ plan.mode==='priority' ? `0${index+1} / ` : '' }}{{ card.moduleLabel }}</em>{{ card.label }}</span>
        <SharedMetric :metric="card" :animate="state==='assembling'" />
        <span class="node-change">{{ card.changeLabel || metricStatus(card) }}</span>
        <span class="node-boundary" v-if="card.state!=='available'">{{ metricStatus(card) }} · 查看依据 ↗</span>
      </button>
    </div>
    <div v-else class="focus-no-data"><strong>当前没有足够依据生成数据节点</strong><p>保留真实数据边界，可返回全域核对读取状态。</p></div>
    <div class="focus-status"><span v-for="item in plan.coverage" :key="item.code"><b>{{ item.code.toUpperCase() }}</b><i :class="{partial:item.status!=='已读取'}"></i>{{ item.status }} · {{ item.count }} 项</span></div>
    <section v-if="plan.trendRequested" class="focus-trend"><h3>按问题生成 · 趋势观察</h3><template v-if="plan.trend"><span>{{ plan.trend.label }} · {{ plan.trend.periodLabel }}</span><MetricVisualization :visualization="plan.trend.visualization" :metric-label="plan.trend.label" @select="emit('focus',plan.trend.id)" /></template><p v-else>当前范围未提供可核验的历史序列，暂不生成趋势图。</p></section>
    <section v-if="state==='ready'" class="focus-insight-panel" aria-live="polite"><small>AI INSIGHT · 当前证据</small><p>{{ plan.insight }}</p><div v-if="primary"><button v-if="plan.moduleCode" type="button" @click="emit('open',plan.moduleCode)">查看 {{ modeLabel }} 详情 ↗</button><button type="button" @click="emit('focus',primary.id)">查看证据</button><button type="button" @click="emit('discuss',primary.id)">讨论这项</button></div><footer>各节点保留原始统计口径；{{ demo ? '当前为演示数据。' : '数据来源与完整周期请展开证据核对。' }}</footer></section>
  </section>
</template>
<style scoped>
