ent:center;gap:8px;width:clamp(140px,25%,240px);padding:12px 6px;border:0;border-radius:50%;background:radial-gradient(ellipse,#17496a30,transparent 70%);color:#d6edff;text-align:center;transition:background .2s}.floating-metric:hover{background:radial-gradient(ellipse,#2f628b55,transparent 72%)}.floating-metric .shared-value{font-size:clamp(27px,3vw,43px)}.floating-metric.geo-core .shared-value{font-size:58px}.node-label{display:grid;gap:5px;font-size:11px;color:#a4bed3}.node-label em{font-size:10px;font-style:normal;letter-spacing:.12em;color:var(--focus-accent)}.node-change{font-size:11px;color:#adccdf}.node-boundary{font-size:10px;color:#d9be91}.is-assembling .floating-metric{animation:assembleMetric .55s cubic-bezier(.2,.8,.2,1) both;animation-delay:var(--node-delay)}.focus-status{display:flex;justify-content:center;flex-wrap:wrap;gap:20px;border-top:1px solid #759eb52b;border-bottom:1px solid #759eb52b;padding:15px;font-size:11px;color:#9db6cb}.focus-status span{display:flex;align-items:center;gap:7px}.focus-status b{color:#c7deef;font-size:11px}.focus-status i{width:5px;height:5px;background:#71d8c5;border-radius:50%}.focus-status i.partial{background:#d0bb8f}.focus-insight-panel{max-width:860px;margin:24px auto 0;animation:insightArrive .4s ease-out both}.focus-insight-panel small{font-size:10px;color:var(--focus-accent);letter-spacing:.12em}.focus-insight-panel p{font-size:16px;line-height:1.9;color:#d5e6f3;margin:12px 0 20px}.focus-insight-panel>div{display:flex;gap:9px;flex-wrap:wrap}.focus-insight-panel footer{font-size:10px;color:#7f9ab2;margin-top:16px}.focus-no-data{display:grid;align-content:center;text-align:center;min-height:310px}.focus-no-data strong{font-weight:500;font-size:18px}.focus-no-data p,.focus-trend p{font-size:12px;color:#8da8be}.focus-trend{max-width:780px;margin:24px auto}.focus-trend h3{font-size:15px;font-weight:500}.focus-trend>span{font-size:11px;color:#9bb8d0}.focus-trend :deep(.trend){height:160px}@keyframes growRelation{from{stroke-dashoffset:1;opacity:0}to{stroke-dashoffset:0;opacity:1}}@keyframes assembleMetric{from{opacity:0;filter:blur(8px);transform:translate(-50%,-50%)}to{opacity:1;filter:blur(0);transform:translate(-50%,-50%)}}@keyframes insightArrive{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@media(max-width:1300px){.focus-response{padding:22px 16px}.floating-metric .shared-value{font-size:29px}.floating-metric.geo-core .shared-value{font-size:44px}.metric-space{height:460px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
